import{_ as e,a0 as p,w as u,s as m,ao as r,I as i,x as l,a1 as n,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Linux 平台上的寫作者必備工具 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 平台上的寫作者必備工具 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 平台上的寫作者必備工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 平台上的寫作者必備工具 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20181109 Must-Have Tools for Writers on the Linux Platform","title":"Linux 平台上的寫作者必備工具","tag":"201911","desc":""},"relativePath":"201911/20181109 Must-Have Tools for Writers on the Linux Platform.md","filePath":"[post].md"}'),f={name:"201911/20181109 Must-Have Tools for Writers on the Linux Platform.md"};function d(a,t,x,g,w,L){const o=p("Link");return u(),m("div",null,[t[35]||(t[35]=r('<h1 id="linux-平台上的寫作者必備工具" tabindex="-1">Linux 平台上的寫作者必備工具 <a class="header-anchor" href="#linux-平台上的寫作者必備工具" aria-label="Permalink to “Linux 平台上的寫作者必備工具”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201911/25/000129eee2zydelz22vj9h.jpg" alt=""></p><p>我從事作家已有 20 多年了。我撰寫了數千篇有關各種技術主題的文章和指南，並撰寫了 40 多本小説。因此，書面文字不僅對我很重要，還很熟悉，成為了我的第二種自然交流的方式。在過去的二十年中（而且還在繼續），我幾乎都是在 Linux 平台上完成的所有工作。我必須承認，在早期，這並不總是那麼容易。格式並不總是與編輯器所需要的相吻合，在某些情況下，開源平台根本沒有完成工作所需的必要工具。</p><p>那時已經過去，現在已經不同了。</p><p>Linux 演進和基於 Web 的工具的相得益彰使得它可以讓任何寫作者都能在 Linux 上完成工作（並且做得很好）。但是你需要什麼工具？你可能會驚訝地發現，在某些情況下，使用 100％ 開源的工具無法有效完成這項工作。不過即使如此，工作總是可以完成的。讓我們來看看我作為技術作家和小説作者一直使用的工具。我將通過小説和非小説類的寫作過程來概述這一點（因為過程不同，需要特定的工具）。</p><p>對認真的 Linux 硬核用户預先做個預警。很久以前，我就放棄了使用 LaTeX 和 DocBook 之類的工具進行寫作。為什麼？因為對我而言，重點必須放在內容上，而不是過程上。當你面臨最後期限時，必須以效率為先。</p><h3 id="非小説類" tabindex="-1">非小説類 <a class="header-anchor" href="#非小説類" aria-label="Permalink to “非小説類”">​</a></h3>',7)),i("p",null,[t[2]||(t[2]=l("我們將從非虛構寫作入手，因為這是兩者中較簡單的過程。為了編寫技術指南，我與不同的編輯人員合作，並且在某些情況下，必須將內容複製/粘貼到 CMS 中。但是就像我的小説一樣，整個過程總是從 Google 雲端硬盤開始。在這一點上，許多開源純粹主義者會轉身走開。不用擔心，你始終可以選擇將所有文件保存在本地，也可以使用更開放友好的雲服務（例如 ",-1)),n(o,{href:"https://www.zoho.com/"},{default:s(()=>[...t[0]||(t[0]=[l("Zoho",-1)])]),_:1}),t[3]||(t[3]=l(" 或 ",-1)),n(o,{href:"https://nextcloud.com/"},{default:s(()=>[...t[1]||(t[1]=[l("nextCloud",-1)])]),_:1}),t[4]||(t[4]=l("）。",-1))]),i("p",null,[t[6]||(t[6]=l("為什麼要從雲端開始？多年來，我發現我需要能夠隨時隨地訪問那些內容。最簡單的解決方案是遷移到雲上。我對丟失工作成果這件事也很偏執。為此，我使用了 ",-1)),n(o,{href:"https://www.insynchq.com"},{default:s(()=>[...t[5]||(t[5]=[l("Insync",-1)])]),_:1}),t[7]||(t[7]=l(" 之類的工具來使我的 Google 雲端硬盤與桌面保持同步。有了桌面同步功能，我知道我的工作成果總是有備份，以防萬一 Google 雲端硬盤出了問題。",-1))]),i("p",null,[t[9]||(t[9]=l("對於那些我必須與之一起將內容輸入到內容管理系統（CMS）的客户，該過程到此結束。我可以直接從 Google 文檔複製/粘貼到 CMS 中，並完成此操作。當然，對於技術內容，總是涉及到屏幕截圖。為此，我使用 ",-1)),n(o,{href:"https://www.gimp.org/"},{default:s(()=>[...t[8]||(t[8]=[l("Gimp",-1)])]),_:1}),t[10]||(t[10]=l("，它使得截取屏幕截圖變得簡單：",-1))]),t[36]||(t[36]=i("p",null,[i("img",{src:"https://lcom.static.linuxfound.org/sites/lcom/files/writingtools_1.jpg",alt:"screenshot with Gimp",title:"screenshot with Gimp"})],-1)),t[37]||(t[37]=i("p",null,[i("em",null,"圖 1：使用 Gimp 截屏。")],-1)),t[38]||(t[38]=i("ol",null,[i("li",null,"打開 Gimp。"),i("li",null,"單擊“文件>創建>屏幕快照”。"),i("li",null,"選擇單個窗口、整個屏幕或要抓取的區域（圖 1）。"),i("li",null,"單擊“抓取”。")],-1)),i("p",null,[t[12]||(t[12]=l("我的大多數客户傾向於使用 Google 文檔，因為我可以共享文件夾，以便他們可以可靠地訪問該內容。我有一些無法使用 Google 文檔的客户，因此我必須將文件下載為可以使用的格式。為此，我要做的是下載 .odt 格式，以 ",-1)),n(o,{href:"https://www.libreoffice.org/"},{default:s(()=>[...t[11]||(t[11]=[l("LibreOffice",-1)])]),_:1}),t[13]||(t[13]=l(" 打開文檔（圖 2），根據需要設置格式，保存為客户所需的格式，然後發送文檔。",-1))]),t[39]||(t[39]=i("p",null,[i("img",{src:"https://lcom.static.linuxfound.org/sites/lcom/files/writingtools_2.jpg",alt:"Google Doc",title:"Google Doc"})],-1)),t[40]||(t[40]=i("p",null,[i("em",null,"圖 2：在 LibreOffice 中打開我下載的 Google 文檔。")],-1)),t[41]||(t[41]=i("p",null,"非小説類作品這樣就行了。",-1)),t[42]||(t[42]=i("h3",{id:"小説類",tabindex:"-1"},[l("小説類 "),i("a",{class:"header-anchor",href:"#小説類","aria-label":"Permalink to “小説類”"},"​")],-1)),t[43]||(t[43]=i("p",null,"這裏會稍微變得有點複雜。開始的步驟是相同的​​，因為我總是在 Google 文檔中寫小説的每個初稿。完成後，我將文件下載到 Linux 桌面，在 LibreOffice 中打開文件，根據需要設置格式，然後另存為編輯器支持的文件類型（不幸的是，這意味着是 .docx）。",-1)),i("p",null,[t[15]||(t[15]=l("該過程的下一步變得有些瑣碎。我的編輯更喜歡使用註釋來跟蹤更改（因為這使我們倆閲讀文檔和做出更改一樣容易）。因此，一個 60k 的 word 文檔可以包含成百上千的註釋，這會使 LibreOffice 慢的像爬一樣。從前，你可以增加用於文檔的內存，但是從 LibreOffice 6 開始，這不再可行。這意味着任何較大的、像小説一樣長的、帶有大量註釋的文檔都將無法使用。因此，我不得不採取一些極端的措施，使用 ",-1)),n(o,{href:"https://www.wps.com/en-US/"},{default:s(()=>[...t[14]||(t[14]=[l("WPS Office",-1)])]),_:1}),t[16]||(t[16]=l("（圖 3）。儘管這不是開源解決方案，但 WPS Office 在文檔中包含大量註釋的情況下做得很好，因此無需處理 LibreOffice 所帶來的麻煩（當處理帶有數百個註釋的大型文件時）。",-1))]),t[44]||(t[44]=i("p",null,[i("img",{src:"https://lcom.static.linuxfound.org/sites/lcom/files/writingtools_3.jpg",alt:"comments",title:"comments"})],-1)),t[45]||(t[45]=i("p",null,[i("em",null,"圖 3：WPS 可以輕鬆處理大量註釋。")],-1)),i("p",null,[t[18]||(t[18]=l("一旦我和我的編輯完成了對書的編輯（所有評論都已刪除），我就可以在 LibreOffice 中打開文件進行最終格式化。格式化完成後，我將文件保存為 .html 格式，然後以 ",-1)),n(o,{href:"https://calibre-ebook.com/"},{default:s(()=>[...t[17]||(t[17]=[l("Calibre",-1)])]),_:1}),t[19]||(t[19]=l(" 打開文件以將文件導出為 .mobi 和 .epub 格式。",-1))]),t[46]||(t[46]=r('<p>對於希望在 Amazon、Barnes＆Noble、Smashwords 或其他平台上出版的任何人，Calibre 都是必備工具。Caliber 比其他類似解決方案更好地方是，它使你可以直接編輯 .epub 文件（圖 4）。對於 Smashword 來説，這是絕對必要的（因為導出過程將添加 Smashwords 轉換工具上不接受的元素）。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/writingtools_4.jpg" alt="Calibre" title="Calibre"></p><p><em>圖 4：直接在 Calibre 中編輯 epub 文件。</em></p><p>寫作過程結束後（或有時在等待編輯完成一校時），我將開始為書製作封面。該任務完全在 Gimp 中處理（圖 5）。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/writingtools_5.jpg" alt="Using Gimp" title="Using Gimp"></p><p><em>圖 5：在 Gimp 中創建 POTUS 的封面。</em></p><p>這樣就完成了在 Linux 平台上創建小説的過程。由於文檔的篇幅以及某些編輯人員的工作方式，與創建非小説類的過程相比，它可能會變得有些複雜，但這遠沒有挑戰性。實際上，在 Linux 上創建小説與其他平台一樣簡單（並且更可靠）。</p><h3 id="希望這可以幫助你" tabindex="-1">希望這可以幫助你 <a class="header-anchor" href="#希望這可以幫助你" aria-label="Permalink to “希望這可以幫助你”">​</a></h3><p>我希望這可以幫助有抱負的作家有信心在 Linux 平台上進行寫作。還有許多其他工具可供使用，但是多年來我在這裏列出的工具很好地服務了我。而且，儘管我確實使用了幾個專有的工具，但只要它們在 Linux 上都能正常運行，我覺得是可以的。</p><hr>',10)),i("p",null,[t[21]||(t[21]=l("via: ",-1)),n(o,{href:"https://www.linux.com/learn/2018/11/must-have-tools-writers-linux-platform"},{default:s(()=>[...t[20]||(t[20]=[l("https://www.linux.com/learn/2018/11/must-have-tools-writers-linux-platform",-1)])]),_:1})]),i("p",null,[t[26]||(t[26]=l("作者：",-1)),n(o,{href:"https://www.linux.com/users/jlwallen"},{default:s(()=>[...t[22]||(t[22]=[l("Jack Wallen",-1)])]),_:1}),t[27]||(t[27]=l(" 選題：",-1)),n(o,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[23]||(t[23]=[l("lujun9972",-1)])]),_:1}),t[28]||(t[28]=l(" 譯者：",-1)),n(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[24]||(t[24]=[l("wxy",-1)])]),_:1}),t[29]||(t[29]=l(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[25]||(t[25]=[l("wxy",-1)])]),_:1})]),i("p",null,[t[32]||(t[32]=l("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[30]||(t[30]=[l("LCTT",-1)])]),_:1}),t[33]||(t[33]=l(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:s(()=>[...t[31]||(t[31]=[l("Linux中國",-1)])]),_:1}),t[34]||(t[34]=l(" 榮譽推出",-1))])])}const G=e(f,[["render",d]]);export{C as __pageData,G as default};
